searchUrl:
@js:(function(){
var UA='Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36';
var base='https://www.rrssk.com/';
var hd=JSON.stringify({'User-Agent':UA,'Referer':base+'00PB.html'});
var hp=java.get(base+'00PB.html',hd);
var h=hp.body()||'';
var m=h.match(/name="_t" value="([^"]+)"/);
if(!m){throw new Error('请先在书源菜单点“登录”，完成验证码后再搜索');}
var t=m[1];
var ts=Math.floor(Date.now()/1000);
var enc=encodeURIComponent(key).replace(/[!'()*]/g,function(c){return '%'+c.charCodeAt(0).toString(16).toUpperCase();});
var i5=0;
for(var i=0;i<enc.length;i++){i5=(i5*15259+enc.charCodeAt(i)+t.charCodeAt(i%t.length))>>>0;i5=(i5^2630)>>>0;}
i5=(i5+ts)>>>0;
for(var r=0;r<37861;r++){i5=((i5<<5)-i5+21787)>>>0;}
var sig=('00000000'+((i5^297)>>>0).toString(16)).slice(-8);
var body='_t='+encodeURIComponent(t)+'&_ts='+ts+'&_s='+sig+'&keyword='+encodeURIComponent(key);
var hh=JSON.stringify({'User-Agent':UA,'Referer':base+'00PB.html','Content-Type':'application/x-www-form-urlencoded'});
var rp=java.post(base+'?action=search',body,hh);
var loc=rp.header('Location')||'';
if(!loc){throw new Error('搜索被拦截，请先在书源菜单点“登录”完成验证');}
if(loc.indexOf('http')!==0){loc='https://www.rrssk.com'+loc;}
loc=loc.replace(/([?&])page=\d+/,'$1page='+page);
if(!/[?&]page=/.test(loc)){loc+=(loc.indexOf('?')>=0?'&':'?')+'page='+page;}
return loc;
})()

ruleBookInfo.tocUrl:
@js:(function(){
var u=String(book.bookUrl);
var bm=u.match(/book\/([0-9A-Z]+)\.html/);
var id=bm?bm[1]:'';
var pages=0;
try{pages=(String(result).match(/<option[^>]*value="\d+"/g)||[]).length;}catch(e){}
if(pages<1){
  try{pages=(String(java.ajax(u,{'User-Agent':'Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36'})).match(/<option[^>]*value="\d+"/g)||[]).length;}catch(e){}
}
if(pages<1)pages=1;
var body='data='+encodeURIComponent(java.createSymmetricCrypto('AES/CBC/PKCS5Padding','Hi3yccTfyPoxfoexMyZ2ohk0xFgjj1mN','2685853201487428').encryptBase64(JSON.stringify({id:id,page:1})));
return 'https://www.mopbook.com/index.php?action=loadChapterPage&page=1&pages='+pages+'&id='+id+',{"method":"POST","body":"'+body+'"}';
})()

ruleToc.nextTocUrl:
@js:(function(){
var d;
try{d=(typeof result==='string')?JSON.parse(result):result;}catch(e){return '';}
var rows=null;
try{if(typeof d.get==='function'){rows=d.get('data');}else{rows=d.data;}}catch(e){try{rows=d.data;}catch(e2){return '';}}
if(rows==null)return '';
var n=rows.length;
if(n==null&&rows.size){try{n=rows.size();}catch(e){n=0;}}
if(!n||n<100)return '';
var m=String(baseUrl).match(/[?&]page=(\d+)/);
var p=m?parseInt(m[1]):1;
var pm=String(baseUrl).match(/[?&]pages=(\d+)/);
var pages=pm?parseInt(pm[1]):100;
if(p>=pages||p>=100)return '';
var next=p+1;
var im=String(baseUrl).match(/[?&]id=([0-9A-Z]+)/);
var id=im?im[1]:'';
if(!id){var bm=String(book.bookUrl).match(/book\/([0-9A-Z]+)\.html/);id=bm?bm[1]:'';}
var body='data='+encodeURIComponent(java.createSymmetricCrypto('AES/CBC/PKCS5Padding','Hi3yccTfyPoxfoexMyZ2ohk0xFgjj1mN','2685853201487428').encryptBase64(JSON.stringify({id:id,page:next})));
return 'https://www.mopbook.com/index.php?action=loadChapterPage&page='+next+'&pages='+pages+'&id='+id+',{"method":"POST","body":"'+body+'"}';
})()
